import java.io.*;
import java.util.*;

public class Main {
    static final long M = 1000000007;
    static FastScanner sc = new FastScanner();
    static FastWriter out = new FastWriter();

    public static void main(String[] args) {
        long N = sc.nextLong();
        long K = sc.nextLong();
        if (N == 0) {
            out.print("0\n");
            out.close();
            return;
        }
        N = (2 * N - 1) % M;
        long z = getx(K);
        long res = (z * N + 1) % M;
        out.print(res + "\n");
        out.close();
    }

    static long getx(long N) {
        if (N < 30) {
            return (1L << (int) N) % M;
        }
        if (N % 2 == 0) {
            long Y = getx(N >> 1);
            return (Y * Y) % M;
        }
        return (getx(N - 1) * 2) % M;
    }

    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1024];
        private int ptr = 0;
        private int buflen = 0;

        private int readByte() throws IOException {
            if (buflen == -1) throw new InputMismatchException();
            if (ptr >= buflen) {
                buflen = in.read(buffer);
                ptr = 0;
                if (buflen <= 0) return -1;
            }
            return buffer[ptr++];
        }

        private boolean isSpace(int x) {
            return (x == ' ' || x == '\n' || x == '\r' || x == '\t' || x == -1);
        }

        public long nextLong() {
            try {
                int c = readByte();
                while (isSpace(c)) c = readByte();
                boolean minus = false;
                if (c == '-') {
                    minus = true;
                    c = readByte();
                }
                long res = 0;
                do {
                    if (c < '0' || c > '9') throw new InputMismatchException();
                    res = res * 10 + (c - '0');
                    c = readByte();
                } while (!isSpace(c));
                return minus ? -res : res;
            } catch (IOException e) {
                throw new InputMismatchException();
            }
        }
    }

    static class FastWriter {
        private final BufferedWriter writer = new BufferedWriter(new OutputStreamWriter(System.out));

        public void print(String s) {
            try {
                writer.write(s);
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }

        public void close() {
            try {
                writer.flush();
                writer.close();
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }
    }
}
